// Note: OpenProject's API key for this integration lacks permission to list/search
// all users (403 on /api/v3/users), so name-to-ID resolution can't be done live.
// Add teammates here as needed.
const USER_NAME_TO_ID = {
  'đàm quốc khánh': 21,
  'dam quoc khanh': 21,
  'khanh': 21,
};

const input = $input.first().json || {};
const overrideUserName = input['OpenProject User Name'];
const overrideDate = input['Reference Date (YYYY-MM-DD)'];

const userName = (overrideUserName && overrideUserName.trim() !== '') ? overrideUserName.trim() : 'Đàm Quốc Khánh';
const normalizedName = userName.toLowerCase();
const userId = USER_NAME_TO_ID[normalizedName];
if (!userId) {
  throw new Error(`Unknown user name "${userName}". Add it to USER_NAME_TO_ID in this node's code.`);
}

const now = (overrideDate && overrideDate !== '') ? new Date(overrideDate + 'T00:00:00Z') : new Date();

const day = now.getDay();
const diffToMonday = day === 0 ? -6 : 1 - day;
const monday = new Date(now);
monday.setDate(now.getDate() + diffToMonday);
monday.setHours(0, 0, 0, 0);
const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);

function fmtShort(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}/${mm}`;
}
function fmtISO(d) {
  return d.toISOString().split('T')[0];
}
function getWeekNumber(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

const weekNumber = getWeekNumber(monday);
const year = monday.getFullYear();
const saturday = new Date(friday);
saturday.setDate(friday.getDate() + 1);

return [{
  json: {
    userId,
    userName,
    mondayDate: fmtISO(monday),
    fridayDate: fmtISO(friday),
    filterEndDate: fmtISO(saturday),
    cardTitle: `${fmtShort(monday)} - ${fmtShort(friday)}/${year}`,
    weekNumber,
    year
  }
}];

const lists = $input.all().map(i => i.json);
const target = lists.find(l => l.name === 'Kh\u00e1nh');
if (!target) {
  throw new Error("List 'Kh\u00e1nh' not found on board");
}
return [{ json: { listId: target.id } }];
